const threshold = $input.item.json.threshold;
const confidence = $('Confidence Check Webhook').item.json.body?.confidence ?? 0;
const needsHuman = $('Confidence Check Webhook').item.json.body?.needsHuman ?? false;
const shouldEscalate = needsHuman || confidence < threshold;
return [{
  json: {
    confidence,
    threshold,
    shouldEscalate,
    reason: shouldEscalate ? (needsHuman ? 'agent-request' : 'low-confidence') : 'auto'
  }
}];
